import java.util.*;
public class TestMain{static final class S implements UserStore{Map<String,User>d=new HashMap<>();int finds;boolean failSave,failDelete;public Optional<User>find(String id){finds++;return Optional.ofNullable(d.get(id));}public void save(User u){if(failSave)throw new IllegalStateException("save");d.put(u.id(),u);}public void delete(String id){if(failDelete)throw new IllegalStateException("delete");d.remove(id);}}static final class C implements UserCache{Map<String,Optional<User>>d=new HashMap<>();public Optional<Optional<User>>get(String id){return d.containsKey(id)?Optional.of(d.get(id)):Optional.empty();}public void put(String id,Optional<User>u){d.put(id,u);}public void evict(String id){d.remove(id);}}
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}public static void main(String[]a){S s=new S();C c=new C();CachedUserRepository r=new CachedUserRepository(s,c);check(r.find("x").isEmpty(),"missing");check(r.find("x").isEmpty()&&s.finds==1,"negative cache");User u=new User("x","A");r.save(u);check(r.find("x").orElseThrow().equals(u)&&s.finds==1,"write through");s.failSave=true;try{r.save(new User("x","B"));throw new AssertionError();}catch(IllegalStateException e){}check(c.d.get("x").orElseThrow().name().equals("A"),"cache poisoned");s.failSave=false;s.failDelete=true;try{r.delete("x");throw new AssertionError();}catch(IllegalStateException e){}check(c.d.containsKey("x"),"premature eviction");s.failDelete=false;r.delete("x");check(!c.d.containsKey("x")&&!s.d.containsKey("x"),"delete");System.out.println("OK");}}
